const fs=require("node:fs"),path=require("node:path");
const {downloadPinned,extractPinnedZip,hashFile}=require("./scripts/flosi-qa-download");
const pins=require("./scripts/flosi-qa-artifacts.json");
(async()=>{const records=[];for(const pack of [...pins.assets,pins.llama]){const root=path.join("/workspace/work/flosi-phase3/artifact-validation",pack.id);const archive=path.join(root,"archive.zip"),dest=path.join(root,"extracted");await downloadPinned(pack,archive);await extractPinnedZip(archive,dest);const files=require("./scripts/flosi-qa").walkFiles(dest);if(!files.some(f=>path.basename(f)===pack.sourceBinary))throw Error("Missing pinned binary");records.push({id:pack.id,url:pack.url,sha256:hashFile(archive),bytes:fs.statSync(archive).size,files:files.map(f=>({path:path.relative(dest,f),sha256:hashFile(f),size:fs.statSync(f).size})),executed:false});console.log(pack.id,"verified archive, no Windows execution");}fs.writeFileSync("/workspace/work/flosi-phase3/native-archives.json",JSON.stringify(records,null,2));})().catch(e=>{console.error(e);process.exitCode=1});
